#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
# -*- coding: utf-8 -*-
r"""项目内 source 卡校验（projects/*/sources）。

为什么需要它
------------
`kb_lint.py` 只扫 `wiki/`。综述工程把 source 卡放在 `projects/<slug>/sources/`，
那是**无人校验区**：frontmatter 写坏、回链指向不存在的提取件、wikilink 全断，
都不会有任何工具报警。本工具就是补这个口子。

校验项（每项都有正例 + 反例夹具）
--------------------------------
P1  frontmatter 可解析：`kb_lib.split_frontmatter` **且** `yaml.safe_load` 均通过
    （前者是本库读取路径，后者能抓住"含冒号未加引号"这类静默失效）
P2  必填字段非空
P3  `type: source`
P4  `authors` 三重校验：list / 每项 str / 无结构破坏字符
P5  `sources:` 首条是 `[[raw/…]]` 或 `[[projects/…]]` 回链
P6  回链目标文件真实存在
P7  `source_url` 与 `doi` 自洽
P8  正文 wikilink 可解析（页面链接查页面名集合，资源链接查文件系统；剔除代码块）
P9  `## 批判性评估` 存在、非空、且至少 1 个 `⚠️` 就地标记
P10 关键数字表存在（≥3 行表格）
P11 `updated >= created`
P12 `si_status` 取值合法（若给出）
P13 `journal_tier` ∈ T0..T4

用法
----
    python tools/qc_proj_sources.py                    # 自动扫 projects/*/sources
    python tools/qc_proj_sources.py --dir projects/myproj-review/sources
    python tools/qc_proj_sources.py --json
    python tools/qc_proj_sources.py --selftest         # 正反例夹具

退出码：0 全部通过 ｜ 1 有硬问题 ｜ 2 参数/环境错误
"""
import argparse
import glob
import json
import os
import re
import sys

import yaml

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import kb_lib as K  # noqa: E402

REQUIRED = ["type", "created", "updated", "year", "journal", "doi", "source_url",
            "authors", "tags", "summary", "source_reliability", "sources"]
BAD_AUTHOR_CHARS = re.compile(r'[\\"\n\r]')
RESOURCE_EXT = (".md", ".pdf", ".png", ".jpg", ".jpeg", ".svg", ".csv", ".json", ".xml")
TIERS = {"T0", "T1", "T2", "T3", "T4"}


# ---------------------------------------------------------------- 页面名索引
def build_page_index(vault):
    """wiki 页 + 所有项目卡的名字集合（用于解析页面型 wikilink）。"""
    idx = set()
    for pat in ("wiki/**/*.md", "projects/*/sources/*.md"):
        for p in glob.glob(os.path.join(vault, *pat.split("/")), recursive=True):
            idx.add(os.path.splitext(os.path.basename(p))[0])
    return idx


def is_resource(target):
    """资源型链接 = 指向**文件系统里的实体文件**（raw/、projects/、assets/ 前缀）。

    🔴 2026-10-23 修：原实现 `target.endswith(RESOURCE_EXT)` 且 RESOURCE_EXT 含 `.md`
    ⇒ `[[concepts/Foo.md]]` 被当成资源路径去查文件系统，必然 `资源不存在`（假断链）。
    而 Obsidian 的页面链接带 `.md` 是完全合法的写法（`resolve_link` 本来就支持剥后缀）。
    判据改为：**目录前缀**决定资源；`.md` 一律视为页面（除非落在 raw/ 等前缀下）。
    """
    if target.startswith(("raw/", "projects/", "assets/")):
        return True
    ext = os.path.splitext(target)[1].lower()
    return bool(ext) and ext in RESOURCE_EXT and ext != ".md"


def resolve_link(target, vault, page_index):
    """→ (ok, 说明)。资源链接查文件系统，页面链接查页面名集合。"""
    t = target.replace("\\", "/").strip().lstrip("/")
    if is_resource(t):
        cand = os.path.join(vault, *t.split("/"))
        if os.path.exists(cand):
            return True, ""
        # 去掉 .md 后缀再试（Obsidian wikilink 常省略）
        if os.path.exists(cand + ".md"):
            return True, ""
        return False, f"资源不存在：{t}"
    stem = t.split("/")[-1]
    if stem.endswith(".md"):
        stem = stem[:-3]
    if stem in page_index:
        return True, ""
    return False, f"页面不存在：{t}"


# ---------------------------------------------------------------- 单项校验
def check_card(path, vault, page_index):
    """返回 (hard[], soft[])。hard 为结构性错误，soft 为建议。"""
    hard, soft = [], []
    text = K.read_text(path)
    raw, body = K.split_frontmatter(text)
    name = os.path.basename(path)

    # P1 frontmatter
    if not raw.strip():
        return [f"{name}: 无 frontmatter"], []
    try:
        fm = yaml.safe_load(raw)
    except Exception as e:                        # noqa: BLE001
        return [f"{name}: YAML 解析失败（多为含冒号未加引号）：{type(e).__name__}: {e}"], []
    if not isinstance(fm, dict):
        return [f"{name}: frontmatter 不是映射"], []
    fm2 = K.parse_frontmatter(raw)
    if not isinstance(fm2, dict) or not fm2:
        hard.append(f"{name}: kb_lib.parse_frontmatter 解析为空（两条解析路径不一致）")

    # P2 必填
    for k in REQUIRED:
        v = fm.get(k)
        if v is None or (isinstance(v, (str, list, dict)) and len(v) == 0):
            hard.append(f"{name}: 缺必填字段 `{k}`")

    # P3 type
    if fm.get("type") != "source":
        hard.append(f"{name}: type 应为 source，实为 {fm.get('type')!r}")

    # P4 authors
    au = fm.get("authors")
    if au is not None:
        if not isinstance(au, list):
            hard.append(f"{name}: authors 不是 list")
        else:
            for a in au:
                if not isinstance(a, str):
                    hard.append(f"{name}: authors 含非字符串项 {a!r}")
                elif BAD_AUTHOR_CHARS.search(a):
                    hard.append(f"{name}: authors 含结构破坏字符：{a!r}")

    # P5/P6 回链
    src = fm.get("sources")
    if isinstance(src, list) and src:
        first = str(src[0])
        m = re.match(r"^\[\[([^\]|]+)", first)
        if not m:
            hard.append(f"{name}: sources 首条不是 wikilink：{first[:60]}")
        else:
            tgt = m.group(1)
            if not tgt.startswith(("raw/", "projects/")):
                hard.append(f"{name}: sources 首条不是 [[raw/…]] 或 [[projects/…]]：{tgt[:60]}")
            else:
                ok, msg = resolve_link(tgt, vault, page_index)
                if not ok:
                    hard.append(f"{name}: sources 回链{msg}")
    elif "sources" not in fm:
        pass                                      # P2 已报

    # P7 source_url vs doi
    doi = str(fm.get("doi") or "").strip()
    url = str(fm.get("source_url") or "").strip()
    if doi and url:
        nd = K.norm_doi(doi).lower()
        nu = K.norm_doi(url).lower()
        if nd and nu and nd != nu:
            hard.append(f"{name}: source_url 与 doi 不一致（{url[:50]} vs {doi}）")
        if nd and not url.startswith(("https://doi.org/", "https://arxiv.org/")):
            soft.append(f"{name}: source_url 不是 doi.org/arxiv 链接")

    # P8 wikilink
    links = K.extract_outlinks(K.strip_code(body))
    bad = []
    for t in links:
        ok, msg = resolve_link(t, vault, page_index)
        if not ok:
            bad.append(msg)
    if bad:
        hard.append(f"{name}: 断链 {len(bad)} 条 → " + "；".join(bad[:5]))
    if len(links) < 2:
        soft.append(f"{name}: 出链仅 {len(links)} 条（建卡规范要求 ≥2）")

    # P9 批判性评估
    m = re.search(r"^##\s*批判性评估.*?$(.*?)(?=^##\s|\Z)", body, re.M | re.S)
    if not m:
        hard.append(f"{name}: 缺 `## 批判性评估` 节")
    else:
        seg = m.group(1).strip()
        if len(seg) < 40:
            hard.append(f"{name}: 批判性评估节过短（{len(seg)} 字符）")
        if "⚠️" not in seg:
            hard.append(f"{name}: 批判性评估节无 `⚠️` 就地标记")

    # P10 关键数字表
    tbl_rows = len(re.findall(r"^\|[^|\n]*\|", body, re.M))
    if tbl_rows < 3:
        soft.append(f"{name}: 表格行仅 {tbl_rows}（建卡规范要求关键数字表 ≥3 行）")

    # P11 日期
    c, u = str(fm.get("created") or ""), str(fm.get("updated") or "")
    if c and u and u < c:
        hard.append(f"{name}: updated({u}) 早于 created({c})")

    # P12 si_status
    if "si_status" in fm and not K.si_status_ok(str(fm.get("si_status"))):
        hard.append(f"{name}: si_status 非法：{fm.get('si_status')!r}")

    # P13 tier
    tier = fm.get("journal_tier")
    if tier is not None and str(tier) not in TIERS:
        hard.append(f"{name}: journal_tier 非法：{tier!r}")

    return hard, soft


# ---------------------------------------------------------------- 主流程
#: 卡目录里的**元文件**，不是文献卡本身（`index.md` 是本项目人工维护的卡索引，
#: 没有 doi/journal/year，按卡校验必然 HARD 一片）。2026-10-22 加入：
#: 建索引后 QC 从「28 张卡 PASS」变成「29 张 FAIL」，9 条 HARD 全落在 index.md 上。
META_NAMES = frozenset({"index.md"})


def discover(vault):
    dirs = sorted(glob.glob(os.path.join(vault, "projects", "*", "sources")))
    return [d for d in dirs if os.path.isdir(d)]


def run(vault, dirs, as_json=False):
    page_index = build_page_index(vault)
    cards = []
    for d in dirs:
        cards += [p for p in sorted(glob.glob(os.path.join(d, "*.md")))
                  if os.path.basename(p).lower() not in META_NAMES]
    if not cards:
        print("[i] 未发现项目卡")
        return 0
    all_hard, all_soft = [], []
    for p in cards:
        h, s = check_card(p, vault, page_index)
        all_hard += h
        all_soft += s
    if as_json:
        print(json.dumps({"cards": len(cards), "hard": all_hard, "soft": all_soft},
                         ensure_ascii=False, indent=1))
    else:
        print(f"检查 {len(cards)} 张项目卡（{len(dirs)} 个目录）")
        for x in all_hard:
            print(f"  [HARD] {x}")
        for x in all_soft:
            print(f"  [soft] {x}")
        print(f"\n结果：HARD {len(all_hard)} ｜ soft {len(all_soft)} ｜ "
              f"{'PASS' if not all_hard else 'FAIL'}")
    return 0 if not all_hard else 1


# ---------------------------------------------------------------- 自检
def selftest():
    ok = True
    tmp = K.make_temp_dir(prefix="qcproj_")
    try:
        os.makedirs(os.path.join(tmp, "wiki", "concepts"), exist_ok=True)
        os.makedirs(os.path.join(tmp, "projects", "P", "sources"), exist_ok=True)
        os.makedirs(os.path.join(tmp, "projects", "P", "references", "Extract"), exist_ok=True)
        # 关联文件
        K.write_text_verified(os.path.join(tmp, "wiki", "concepts", "概念A.md"),
                              "---\ntype: concept\n---\n# 概念A\n")
        K.write_text_verified(
            os.path.join(tmp, "projects", "P", "references", "Extract", "论文X.md"),
            "# 论文X\n正文\n")

        GOOD = """---
type: source
created: 2026-10-01
updated: 2026-10-22
year: 2026
journal: "Nature"
journal_tier: T0
doi: 10.1038/xyz
source_url: "https://doi.org/10.1038/xyz"
authors:
  - A. Author
  - B. Author
tags:
  - source
summary: "一句话摘要"
source_reliability: "同行评审；样本单一"
si_status: missing
sources:
  - "[[projects/P/references/Extract/论文X.md]]"
---
# 论文X

摘要句。

| 项目 | 值 |
|---|---|
| a | 1 |
| b | 2 |

## 批判性评估

> ⚠️ 自报数字：数值为作者自报，无第三方核验。该活性数据未给出误差棒，也未说明重复次数。

> ⚠️ 单源论断：所提机理目前仅本组报道，尚无第二家独立验证。

## 参见

- [[concepts/概念A]]
"""
        def put(name, text):
            p = os.path.join(tmp, "projects", "P", "sources", name)
            K.write_text_verified(p, text)
            return p

        good = put("good.md", GOOD)
        idx = build_page_index(tmp)
        h, s = check_card(good, tmp, idx)
        print(f"  [{'ok' if not h else 'FAIL'}] 正例 合格卡无 HARD 问题（{h[:1]}）")
        ok = ok and not h

        # 反例 1：summary 含冒号未加引号 → YAML 解析失败
        bad1 = put("b1.md", GOOD.replace('summary: "一句话摘要"', "summary: 摘要: 含冒号"))
        h1, _ = check_card(bad1, tmp, idx)
        c1 = any("YAML 解析失败" in x for x in h1)
        print(f"  [{'ok' if c1 else 'FAIL'}] 反例 含冒号未加引号被检出")
        ok = ok and c1

        # 反例 2：回链指向不存在的提取件
        bad2 = put("b2.md", GOOD.replace("论文X.md]]", "论文Y.md]]"))
        h2, _ = check_card(bad2, tmp, idx)
        c2 = any("资源不存在" in x for x in h2)
        print(f"  [{'ok' if c2 else 'FAIL'}] 反例 回链目标不存在被检出")
        ok = ok and c2

        # 反例 3：正文断链
        bad3 = put("b3.md", GOOD.replace("[[concepts/概念A]]", "[[concepts/不存在的页面]]"))
        h3, _ = check_card(bad3, tmp, idx)
        c3 = any("断链" in x for x in h3)
        print(f"  [{'ok' if c3 else 'FAIL'}] 反例 断链被检出")
        ok = ok and c3

        # 反例 4：批判性评估缺 ⚠️
        bad4 = put("b4.md", GOOD.replace(
            "> ⚠️ 自报数字：数值为作者自报，无第三方核验。该活性数据未给出误差棒，也未说明重复次数。\n\n"
            "> ⚠️ 单源论断：所提机理目前仅本组报道，尚无第二家独立验证。",
            "作者未说明局限，本文数据可靠。作者未说明局限，本文数据可靠。"))
        h4, _ = check_card(bad4, tmp, idx)
        c4 = any("无 `⚠️`" in x for x in h4)
        print(f"  [{'ok' if c4 else 'FAIL'}] 反例 批判性评估无 ⚠️ 标记被检出")
        ok = ok and c4

        # 反例 5：authors 含反斜杠
        bad5 = put("b5.md", GOOD.replace("  - A. Author", r"  - A\\Author"))
        h5, _ = check_card(bad5, tmp, idx)
        c5 = any("结构破坏字符" in x for x in h5)
        print(f"  [{'ok' if c5 else 'FAIL'}] 反例 authors 结构破坏字符被检出")
        ok = ok and c5

        # 反例 6：updated 早于 created
        bad6 = put("b6.md", GOOD.replace("updated: 2026-10-22", "updated: 2026-09-01"))
        h6, _ = check_card(bad6, tmp, idx)
        c6 = any("早于 created" in x for x in h6)
        print(f"  [{'ok' if c6 else 'FAIL'}] 反例 updated 早于 created 被检出")
        ok = ok and c6

        # 正例：资源型 wikilink（带子目录）能解析
        good2 = put("good2.md", GOOD.replace(
            "- [[concepts/概念A]]",
            "- [[concepts/概念A]]\n- [[projects/P/references/Extract/论文X.md]]"))
        h7, _ = check_card(good2, tmp, build_page_index(tmp))
        c7 = not any("断链" in x for x in h7)
        print(f"  [{'ok' if c7 else 'FAIL'}] 正例 资源型 wikilink 可解析")
        ok = ok and c7

        # 正例：**带 .md 的页面型** wikilink 也必须按页面解析（2026-10-23 回归夹具）。
        #   旧实现把任何 `.md` 结尾的目标都当资源 ⇒ `[[concepts/概念A.md]]` 被报「资源不存在」。
        #   这类假断链会让报告失去可信度（真断链混在噪声里）。
        good3 = put("good3.md", GOOD.replace(
            "- [[concepts/概念A]]", "- [[concepts/概念A.md]]"))
        h9, _ = check_card(good3, tmp, build_page_index(tmp))
        c9 = not any("不存在" in x for x in h9)
        print(f"  [{'ok' if c9 else 'FAIL'}] 正例 带 .md 的页面型 wikilink 可解析")
        ok = ok and c9

        # 正例：卡目录里的元文件 index.md 不当作文献卡（否则必然一片 HARD）
        # 反例含义：若 META_NAMES 被删，cards 会变 2、hard 非空。
        import contextlib
        import io
        sdir2 = os.path.join(tmp, "projects", "P2", "sources")
        os.makedirs(sdir2, exist_ok=True)
        K.write_text_verified(os.path.join(sdir2, "good.md"), GOOD)
        K.write_text_verified(os.path.join(sdir2, "index.md"),
                              "---\ntype: output\ntags: [index]\n---\n\n# 卡索引\n\n不是文献卡。\n")
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            rc = run(tmp, [sdir2], as_json=True)
        payload = json.loads(buf.getvalue())
        c8 = rc == 0 and payload["cards"] == 1 and not payload["hard"]
        print(f"  [{'ok' if c8 else 'FAIL'}] 正例 index.md 被排除在文献卡之外"
              f"（cards={payload['cards']}, hard={len(payload['hard'])}）")
        ok = ok and c8
    finally:
        K.remove_temp_dir(tmp)
    print("=== selftest PASS ===" if ok else "=== selftest FAIL ===")
    return 0 if ok else 1


def main():
    K.console_encoding()   # ⚠️/✅ 等符号在 CP936 控制台下会抛 UnicodeEncodeError
    ap = argparse.ArgumentParser(description="项目内 source 卡校验")
    ap.add_argument("--dir", action="append", default=[], help="卡目录（相对库根，可重复）")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()
    if args.selftest:
        return selftest()
    vault = K.VAULT
    if args.dir:
        dirs = [os.path.join(vault, *d.replace("\\", "/").split("/")) for d in args.dir]
        missing = [d for d in dirs if not os.path.isdir(d)]
        if missing:
            print(f"[!] 目录不存在：{missing}", file=sys.stderr)
            return 2
    else:
        dirs = discover(vault)
    return run(vault, dirs, args.json)


if __name__ == "__main__":
    sys.exit(main())
